export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const purgeCutoff = toIsoTimestamp(
      new Date(now.getTime() - DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY),
    );
    const doomed = await orgRepo.listOrgsArchivedBefore(purgeCutoff);

    for (const org of doomed) {
      try {
        await orgRepo.purgeOrganization(org.id);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("workspace purge failed", {
          orgId: org.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || isArchived(org)) continue;

      const { retentionDays } = getPlanLimits(org.plan);

