/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
90→  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
100→  }

  assertNotArchived("Organization", org.id, org);

  const archived = await orgRepo.archiveOrg(input.orgId);

  await emit("organization.deleted", {
    ...envelope(archived.id, actor.userId),
    slug: archived.slug,
  });
110→
  return archived;
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** True once `archivedAt` is at least the retention window before `now`. */
function retentionElapsed(archivedAt: IsoTimestamp, now: Date): boolean {
  return (
    now.getTime() - Date.parse(archivedAt) >=
120→    DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY
  );
}

/**
 * Brings a deleted workspace back. There is no `Actor` for a deleted
 * workspace, so the caller is named by user id and checked against the
 * stored membership.
 */
export async function restoreOrganization(
130→  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) {
    throw new NotFoundError("Organization", orgId);
  }

  if (org.archivedAt !== null && retentionElapsed(org.archivedAt, new Date())) {
    throw new NotFoundError("Organization", orgId);
140→  }

  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
150→    orgResource(orgId),
  );

  if (org.archivedAt === null) {
    return org;
  }

  const restored = await orgRepo.restoreOrg(orgId);

