      orgId: tenant.org.id,
      limit: 20,
      cursor: null,
    });
    expect(audit.items.some((row) => row.action === "organization.deleted" && row.subjectId === tenant.org.id && row.actorId === tenant.userIds.owner)).toBe(true);
    expect(audit.items.some((row) => row.action === "organization.restored" && row.subjectKind === "organization")).toBe(true);

    await runCleanupArchivedJob(new Date());
    expect(await orgRepo.findOrgById(tenant.org.id)).toBeNull();
